import{A as t}from"./chunks/AiCourseLab.d8737767.js";import{L as i}from"./chunks/LessonQuiz.a2e1a013.js";import{d as r,o as s,c as v,H as a,Q as d,_ as l}from"./chunks/framework.68eebb55.js";const c={class:"lesson"},p=d('<div class="meta" data-v-a44d1393><span class="tag" data-v-a44d1393>第 03 / 40 篇</span><span data-v-a44d1393>第一阶段：AI 与大模型基础</span><span data-v-a44d1393>阅读约 12–15 分钟</span></div><h1 data-v-a44d1393>Transformer 与 Attention：ChatGPT 为什么能理解上下文？</h1><p data-v-a44d1393>「吃苹果」和「苹果发布 iPhone」中的同一个词，为什么可以呈现不同语义？关键是 Transformer 的上下文计算。</p><h2 data-v-a44d1393>一、为什么仅有 Embedding 还不够？</h2><p data-v-a44d1393>相同 Token ID 通常对应相同的初始 Token Embedding，但经过 Transformer 后，会形成上下文相关的隐藏状态。</p><div class="visual" data-v-a44d1393><div class="step" data-v-a44d1393>苹果：相同初始 Embedding</div><div class="arrow" data-v-a44d1393>↓ Self-Attention 与 Transformer</div><div class="cols" data-v-a44d1393><div class="panel" data-v-a44d1393>🍎 吃苹果：水果相关表示</div><div class="panel" data-v-a44d1393>📱 苹果发布 iPhone：公司相关表示</div></div><p data-v-a44d1393>注意：GPT 采用因果掩码，句首「苹果」不能直接关注后面的 iPhone；后续位置可以结合前文。</p></div><h2 data-v-a44d1393>二、Self-Attention 是什么？</h2><p data-v-a44d1393>Self-Attention 让当前位置根据 Query 与 Key 的匹配程度，对允许访问位置的 Value 进行加权聚合。</p><p data-v-a44d1393>例如「小明把电脑放在桌子上，因为它太重了」，模型需要综合不同位置的信息来判断「它」的可能指代。</p>',9),h=d(`<p data-v-a44d1393>注意力权重不是模型决策的完整解释。</p><h2 data-v-a44d1393>三、Q、K、V</h2><table data-v-a44d1393><thead data-v-a44d1393><tr data-v-a44d1393><th data-v-a44d1393>名称</th><th data-v-a44d1393>作用</th></tr></thead><tbody data-v-a44d1393><tr data-v-a44d1393><td data-v-a44d1393>Query</td><td data-v-a44d1393>我寻找什么信息？</td></tr><tr data-v-a44d1393><td data-v-a44d1393>Key</td><td data-v-a44d1393>我有什么匹配特征？</td></tr><tr data-v-a44d1393><td data-v-a44d1393>Value</td><td data-v-a44d1393>我能提供什么信息？</td></tr></tbody></table><div class="visual" data-v-a44d1393><div class="step" data-v-a44d1393>输入隐藏状态 X</div><div class="arrow" data-v-a44d1393>↓ 可训练线性投影</div><div class="cols" data-v-a44d1393><div class="panel" data-v-a44d1393>Q = XW<sub data-v-a44d1393>Q</sub></div><div class="panel" data-v-a44d1393>K = XW<sub data-v-a44d1393>K</sub></div></div><div class="step" data-v-a44d1393>V = XW<sub data-v-a44d1393>V</sub></div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>Attention：匹配并聚合信息</div></div><h2 data-v-a44d1393>四、Attention 数学公式</h2><div class="formula" data-v-a44d1393>Attention(Q,K,V) = softmax(QKᵀ / √dₖ) V</div><p data-v-a44d1393>第一步计算 QKᵀ 匹配分数；第二步除以 √dₖ 缩放；第三步 Softmax 转为权重；第四步对 V 加权求和。</p><h3 data-v-a44d1393>手算示例</h3><p data-v-a44d1393>假设已缩放分数为 [1,2,3]，Softmax 约为 [0.09,0.245,0.665]。</p><pre data-v-a44d1393><code data-v-a44d1393>V1=[1,0], V2=[0,1], V3=[1,1]
0.09×V1 + 0.245×V2 + 0.665×V3
= [0.755, 0.910]</code></pre><p data-v-a44d1393>这是无因果约束的教学示例；GPT 类模型首位置不能看到未来 Token。</p><h2 data-v-a44d1393>五、Multi-Head Attention</h2><p data-v-a44d1393>多个注意力头各自拥有投影参数，学习不同的关联模式。结果拼接后再经过线性投影。</p><div class="visual" data-v-a44d1393><div class="step" data-v-a44d1393>输入 X</div><div class="arrow" data-v-a44d1393>↓</div><div class="cols" data-v-a44d1393><div class="panel" data-v-a44d1393>Head 1</div><div class="panel" data-v-a44d1393>Head 2</div></div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>Concat + 输出投影</div></div><div class="formula" data-v-a44d1393>MultiHead = Concat(head₁, …, headₕ) W<sub data-v-a44d1393>O</sub></div><h2 data-v-a44d1393>六、为什么 ChatGPT 不能直接看到未来的 Token？</h2><p data-v-a44d1393>GPT 类模型通常使用 <strong data-v-a44d1393>Causal Self-Attention（因果自注意力）</strong>。处理序列中的某个位置时，只能关注该位置及之前的位置，不能直接访问未来 Token。</p><pre data-v-a44d1393><code data-v-a44d1393>我 → 喜欢 → JavaScript
处理「喜欢」时：可以参考「我」「喜欢」
不能直接参考后面的「JavaScript」</code></pre><h3 data-v-a44d1393>6.1 Causal Mask 如何实现？</h3><p data-v-a44d1393>注意力分数矩阵 S = QKᵀ / √dₖ。Softmax 之前加入掩码 M：当 j ≤ i 时 Mᵢⱼ = 0；当 j &gt; i 时 Mᵢⱼ = −∞。</p><div class="formula" data-v-a44d1393>Attention Weights = softmax(S + M)</div><p data-v-a44d1393>由于 exp(−∞) = 0，未来位置对应的注意力权重为 0。实现时可以采用大负数或专用掩码机制。</p><h3 data-v-a44d1393>6.2 交互实验：因果注意力矩阵</h3>`,23),u=d(`<h3 data-v-a44d1393>6.3 为什么因果掩码重要？</h3><p data-v-a44d1393>如果训练时「喜欢」位置可以直接看到需要预测的「JavaScript」，模型就可能偷看答案。因果掩码保证训练目标符合逐 Token 生成的约束。</p><p data-v-a44d1393><strong data-v-a44d1393>注意：模型可以看到用户已经发送的完整问题，但不能提前看到自己尚未生成的回答。</strong></p><h2 data-v-a44d1393>七、Transformer Block 除了 Attention 还有什么？</h2><p data-v-a44d1393>典型现代 GPT 类 Transformer Block 还包括前馈网络（FFN）、残差连接、归一化等机制。不同架构的顺序可能不同。</p><div class="visual" data-v-a44d1393><strong data-v-a44d1393>Transformer Block（Pre-Norm 概念示意）</strong><div class="step" data-v-a44d1393>输入隐藏状态 X</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>Normalization</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>Causal Self-Attention</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>Residual Add（加上原始输入）</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>Normalization + FFN</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>Residual Add → 输出隐藏状态</div></div><h3 data-v-a44d1393>7.1 Feed Forward Network</h3><p data-v-a44d1393>Attention 主要负责聚合上下文信息，FFN 对每个位置的隐藏状态执行非线性变换。</p><div class="formula" data-v-a44d1393>FFN(x) = W₂ σ(W₁x + b₁) + b₂</div><p data-v-a44d1393>这是经典 FFN 的简化公式。实际现代模型可能使用门控 FFN 等变体。</p><h3 data-v-a44d1393>7.2 Residual Connection</h3><div class="formula" data-v-a44d1393>y = x + F(x)</div><p data-v-a44d1393>残差连接让原始信息有直接传播路径，有助于深层网络的梯度传播与训练。</p><h3 data-v-a44d1393>7.3 Normalization</h3><p data-v-a44d1393>LayerNorm 或 RMSNorm 等归一化操作有助于改善数值尺度和训练稳定性，具体位置随架构变化。</p><h2 data-v-a44d1393>八、TypeScript 工程实践：Attention 与聊天历史有什么关系？</h2><p data-v-a44d1393><strong data-v-a44d1393>Self-Attention 是模型内部机制；聊天历史管理是应用层职责。</strong>模型无法利用未传入的历史消息。</p><p data-v-a44d1393>假设用户先说「我正在学习 React」，再问「它和 Vue 有什么区别？」。如果只发送第二句话，模型就可能缺少「它」指 React 的背景。</p><h3 data-v-a44d1393>8.1 组织多轮 Messages</h3><pre data-v-a44d1393><code data-v-a44d1393>import OpenAI from &quot;openai&quot;;

const client = new OpenAI();
const messages = [
  { role: &quot;system&quot; as const, content: &quot;你是一名前端技术导师。&quot; },
  { role: &quot;user&quot; as const, content: &quot;我正在学习 React。&quot; },
  { role: &quot;assistant&quot; as const, content: &quot;React 是一个 UI 库。&quot; },
  { role: &quot;user&quot; as const, content: &quot;它和 Vue 有什么区别？&quot; },
];

const response = await client.chat.completions.create({
  model: &quot;gpt-4.1-mini&quot;,
  messages,
});
console.log(response.choices[0].message.content);</code></pre><h3 data-v-a44d1393>8.2 为什么上下文窗口有限？</h3><p data-v-a44d1393>模型有上下文长度限制。输入、系统提示词与输出需要符合相应预算；历史越来越长时，应用应裁剪较早消息、摘要或检索相关记忆。</p><div class="visual" data-v-a44d1393><strong data-v-a44d1393>上下文管理流程</strong><div class="step" data-v-a44d1393>完整聊天历史</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>估算 Token 使用量</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>保留关键历史，摘要较早消息</div><div class="arrow" data-v-a44d1393>↓</div><div class="step" data-v-a44d1393>组装 Messages 并调用 LLM</div></div><h3 data-v-a44d1393>8.3 Attention 的计算成本</h3><p data-v-a44d1393>标准全量 Self-Attention 的分数矩阵大小为 n × n，相关计算规模通常随序列长度呈二次增长 O(n²)。实际推理性能还受 KV Cache、FlashAttention、模型结构等影响。</p><h2 data-v-a44d1393>九、本篇总结</h2><table data-v-a44d1393><thead data-v-a44d1393><tr data-v-a44d1393><th data-v-a44d1393>概念</th><th data-v-a44d1393>作用</th></tr></thead><tbody data-v-a44d1393><tr data-v-a44d1393><td data-v-a44d1393>Self-Attention</td><td data-v-a44d1393>动态聚合上下文信息</td></tr><tr data-v-a44d1393><td data-v-a44d1393>Q / K / V</td><td data-v-a44d1393>匹配与信息聚合</td></tr><tr data-v-a44d1393><td data-v-a44d1393>Multi-Head</td><td data-v-a44d1393>从多个表示子空间学习关联</td></tr><tr data-v-a44d1393><td data-v-a44d1393>Causal Mask</td><td data-v-a44d1393>禁止关注未来 Token</td></tr><tr data-v-a44d1393><td data-v-a44d1393>FFN</td><td data-v-a44d1393>非线性变换隐藏状态</td></tr><tr data-v-a44d1393><td data-v-a44d1393>Residual</td><td data-v-a44d1393>改善深层信息与梯度传播</td></tr><tr data-v-a44d1393><td data-v-a44d1393>Messages</td><td data-v-a44d1393>应用层提供多轮上下文</td></tr></tbody></table><h2 data-v-a44d1393>学习疑问与解答</h2><h3 data-v-a44d1393>Q1：Self-Attention 是否根据上下文动态赋予每个 Token 语义？</h3><p data-v-a44d1393>提问日期：2026-10-15</p><p data-v-a44d1393><strong data-v-a44d1393>更准确地说，Self-Attention 动态聚合上下文信息并更新 Token 的向量表示，而不是直接分配语义标签。</strong></p><p data-v-a44d1393>同一个 Token 的初始 Embedding 可以相同，但多层 Transformer 计算后隐藏状态不同。GPT 的因果掩码还限制了当前位置能够访问的上下文。</p><p data-v-a44d1393>复习要点：动态更新的是表示，不是直接给 Token 打标签。</p><h2 data-v-a44d1393>十、课后练习</h2>`,34),m=d('<ol data-v-a44d1393><li data-v-a44d1393>Self-Attention 与 Token Embedding 有什么区别？</li><li data-v-a44d1393>Q、K、V 分别负责什么？为什么需要 Softmax？</li><li data-v-a44d1393>如果 GPT 没有 Causal Mask，训练时会出现什么问题？</li><li data-v-a44d1393>FFN、残差连接和归一化分别有什么作用？</li><li data-v-a44d1393>为什么后端只发送「它和 Vue 有什么区别」可能导致回答不准确？</li></ol><p data-v-a44d1393><strong data-v-a44d1393>工程思考：</strong>如果聊天历史达到 100,000 Tokens，你会如何设计保留、摘要与检索策略？</p><footer data-v-a44d1393><a href="./02-token-and-embedding" data-v-a44d1393>← 上一篇</a><span data-v-a44d1393>第 03 篇</span></footer>',3),f=r({__name:"TransformerLesson",setup(e){return(o,n)=>(s(),v("article",c,[p,a(t,{type:"attention"}),h,a(t,{type:"mask"}),u,a(i,{chapter:3}),m]))}});const _=l(f,[["__scopeId","data-v-a44d1393"]]),k=JSON.parse('{"title":"03 · Transformer 与 Attention：ChatGPT 为什么能理解上下文？","description":"","frontmatter":{"title":"03 · Transformer 与 Attention：ChatGPT 为什么能理解上下文？","outline":"deep"},"headers":[],"relativePath":"guide/ai/chatbot-course/03-transformer-attention.md","filePath":"guide/ai/chatbot-course/03-transformer-attention.md","lastUpdated":1792054297000}'),T={name:"guide/ai/chatbot-course/03-transformer-attention.md"},S=Object.assign(T,{setup(e){return(o,n)=>(s(),v("div",null,[a(_)]))}});export{k as __pageData,S as default};
